//! A message's `<style>` rules, applied to its elements as inline styles (see
//! [`crate::layout::inline_css`]): mail generated by reports and newsletters colours its table
//! cells and sizes its headings with classes (`<td class="title">`), which the layout only reads
//! from `style` attributes. Simple selectors only: a tag, `.class`, `#id`, `*` and combinations of
//! them, chained as descendants (`table.report td`, `>` read as a descendant). Rules with
//! pseudo-classes, attribute selectors or sibling combinators are left out, and so is everything
//! inside at-rules (fonts, dark colours, mobile overrides), but for `@media` rules for a screen
//! as wide as a desktop window's ([`wide_screen`]): a template keeps what a wide screen shows
//! there (a product's picture at its full size). Like all mail, the CSS is hostile input: its
//! size, rule count and selector length are capped.

use std::collections::HashMap;

/// CSS read at most, in bytes.
const MAX_CSS: usize = 256 * 1024;
/// Rules kept at most.
const MAX_RULES: usize = 2_000;
/// Parts of one selector, at most (`a b c …`).
const MAX_PARTS: usize = 8;

/// One part of a selector: a tag, an id and classes, all of which must match (none: any element).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct Compound {
    tag: Option<String>,
    id: Option<String>,
    classes: Vec<String>,
}

#[derive(Clone, Debug)]
struct Rule {
    /// Outermost first; the last part is the element itself.
    parts: Vec<Compound>,
    /// (ids, classes, tags), as CSS weighs them.
    specificity: (u16, u16, u16),
    order: usize,
    decls: Vec<Decl>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct Decl {
    pub prop: String,
    pub value: String,
    pub important: bool,
}

/// An element as selectors see it.
#[derive(Clone, Debug, Default)]
pub(crate) struct El<'a> {
    pub tag: &'a str,
    pub id: Option<&'a str>,
    pub classes: Vec<&'a str>,
}

/// The rules of a message's style sheets, indexed by what their last part needs.
#[derive(Debug, Default)]
pub(crate) struct Sheet {
    rules: Vec<Rule>,
    by_id: HashMap<String, Vec<usize>>,
    by_class: HashMap<String, Vec<usize>>,
    by_tag: HashMap<String, Vec<usize>>,
    any: Vec<usize>,
}

/// `text` without `/* … */` comments.
fn without_comments(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(i) = rest.find("/*") {
        out.push_str(rest.get(..i).unwrap_or(""));
        rest = match rest.get(i + 2..).and_then(|r| r.find("*/").map(|j| (r, j))) {
            Some((r, j)) => r.get(j + 2..).unwrap_or(""),
            None => "",
        };
    }
    out.push_str(rest);
    out
}

/// A declaration block's declarations (`color: red; font-size: 12px !important`).
pub(crate) fn declarations(block: &str) -> Vec<Decl> {
    block
        .split(';')
        .filter_map(|d| {
            let (k, v) = d.split_once(':')?;
            let prop = k.trim().to_ascii_lowercase();
            if prop.is_empty() || !prop.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
                return None;
            }
            let v = v.trim();
            let lower = v.to_ascii_lowercase();
            let (value, important) = match lower.find("!important") {
                Some(i) => (v.get(..i).unwrap_or(v).trim(), true),
                None => (v, false),
            };
            // Nothing that could close the attribute it goes into, or run.
            if value.is_empty() || value.contains(['"', '<', '>', '{', '}']) || lower.contains("expression(") || lower.contains("javascript:") {
                return None;
            }
            Some(Decl { prop, value: value.to_string(), important })
        })
        .collect()
}

/// One selector (`table.report td`), or `None` when it uses what isn't supported.
fn selector(text: &str) -> Option<Vec<Compound>> {
    let text = text.trim();
    if text.is_empty() || text.contains([':', '[', '+', '~', '(', '\\', '"', '\'']) {
        return None;
    }
    let mut parts = Vec::new();
    for word in text.replace('>', " ").split_whitespace() {
        if parts.len() >= MAX_PARTS {
            return None;
        }
        let mut c = Compound::default();
        // Split at `.` and `#`, keeping which started each piece.
        let mut piece = String::new();
        let mut kind = ' ';
        let flush = |kind: char, piece: &mut String, c: &mut Compound| -> Option<()> {
            let p = std::mem::take(piece);
            match kind {
                ' ' if p == "*" || p.is_empty() => {}
                ' ' => c.tag = Some(p.to_ascii_lowercase()),
                '.' if !p.is_empty() => c.classes.push(p.to_ascii_lowercase()),
                '#' if !p.is_empty() => c.id = Some(p.to_ascii_lowercase()),
                _ => return None,
            }
            Some(())
        };
        for ch in word.chars() {
            match ch {
                '.' | '#' => {
                    flush(kind, &mut piece, &mut c)?;
                    kind = ch;
                }
                ch if ch.is_alphanumeric() || ch == '-' || ch == '_' || ch == '*' => piece.push(ch),
                _ => return None,
            }
        }
        flush(kind, &mut piece, &mut c)?;
        parts.push(c);
    }
    (!parts.is_empty()).then_some(parts)
}

impl Compound {
    fn matches(&self, e: &El<'_>) -> bool {
        self.tag.as_deref().is_none_or(|t| e.tag.eq_ignore_ascii_case(t))
            && self.id.as_deref().is_none_or(|id| e.id.is_some_and(|x| x.eq_ignore_ascii_case(id)))
            && self.classes.iter().all(|c| e.classes.iter().any(|x| x.eq_ignore_ascii_case(c)))
    }
}

/// The width a message is read at, for its `@media` rules: a desktop window's, as Outlook's.
const SCREEN: f32 = 1024.0;

/// Whether an at-rule's head (`@media only screen and (min-width: 600px)`) is for a screen as
/// wide as a desktop window: a screen (or any medium), every condition one about its width that
/// holds at [`SCREEN`]. Print, dark colours, a phone's width and anything not understood aren't.
fn wide_screen(head: &str) -> bool {
    let head = head.to_ascii_lowercase();
    let Some(queries) = head.strip_prefix("@media") else { return false };
    queries.split(',').any(|q| {
        // What's in brackets is a condition; the words around them say which medium.
        let mut words = String::new();
        let mut conditions = 0usize;
        let mut rest = q;
        while let Some(open) = rest.find('(') {
            words.push_str(rest.get(..open).unwrap_or(""));
            words.push(' ');
            let Some(close) = rest.get(open..).and_then(|r| r.find(')')) else { return false };
            let feature = rest.get(open + 1..open + close).unwrap_or("");
            rest = rest.get(open + close + 1..).unwrap_or("");
            let Some((name, value)) = feature.split_once(':') else { return false };
            let Some(px) = value.trim().strip_suffix("px").and_then(|n| n.trim().parse::<f32>().ok()) else { return false };
            let holds = match name.trim() {
                "min-width" | "min-device-width" => px <= SCREEN,
                "max-width" | "max-device-width" => px >= SCREEN,
                _ => false,
            };
            if !holds {
                return false;
            }
            conditions += 1;
        }
        words.push_str(rest);
        let mut medium = false;
        for word in words.split_whitespace() {
            match word {
                "screen" | "all" => medium = true,
                "only" | "and" => {}
                _ => return false,
            }
        }
        // `@media screen` alone says nothing about width: a rule for every screen is one.
        conditions > 0 || medium
    })
}

impl Sheet {
    /// The rules in a message's style sheets (their text, one after another).
    pub(crate) fn parse(css: &str) -> Sheet {
        let css = css.get(..css.len().min(MAX_CSS)).unwrap_or("");
        let css = without_comments(css).replace("<!--", " ").replace("-->", " ");
        let mut sheet = Sheet::default();
        sheet.read(&css, 0);
        sheet
    }

    /// The rules in `css`, and (`nested`: how many at-rules it's in) those of the `@media` blocks
    /// in it that are for a wide screen.
    fn read(&mut self, css: &str, nested: usize) {
        let sheet = self;
        let mut rest = css;
        while sheet.rules.len() < MAX_RULES {
            let Some(open) = rest.find('{') else { break };
            let before = rest.get(..open).unwrap_or("");
            let head = before.trim();
            // `@import …;` before a block: drop it, and read on from after it (where it ends
            // in what's left, not in that trimmed: after white space the rule that followed was
            // cut into, and lost).
            if let Some(semi) = before.rfind(';').filter(|_| head.contains('@')) {
                rest = rest.get(semi + 1..).unwrap_or("");
                continue;
            }
            // The block, to its matching `}` (at-rules nest).
            let mut depth = 0usize;
            let mut close = None;
            for (i, ch) in rest.get(open..).unwrap_or("").char_indices() {
                match ch {
                    '{' => depth += 1,
                    '}' => {
                        depth = depth.saturating_sub(1);
                        if depth == 0 {
                            close = Some(open + i);
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let Some(close) = close else { break };
            let body = rest.get(open + 1..close).unwrap_or("");
            rest = rest.get(close + 1..).unwrap_or("");
            if head.starts_with('@') && nested < 2 && wide_screen(head) {
                sheet.read(body, nested + 1);
                continue;
            }
            if head.starts_with('@') || body.contains('{') {
                continue;
            }
            let decls = declarations(body);
            if decls.is_empty() {
                continue;
            }
            for sel in head.split(',') {
                let Some(parts) = selector(sel) else { continue };
                let specificity = parts.iter().fold((0u16, 0u16, 0u16), |(a, b, c), p| {
                    (
                        a.saturating_add(u16::from(p.id.is_some())),
                        b.saturating_add(u16::try_from(p.classes.len()).unwrap_or(u16::MAX)),
                        c.saturating_add(u16::from(p.tag.is_some())),
                    )
                });
                let i = sheet.rules.len();
                let Some(last) = parts.last() else { continue };
                match (&last.id, last.classes.first(), &last.tag) {
                    (Some(id), _, _) => sheet.by_id.entry(id.clone()).or_default().push(i),
                    (None, Some(c), _) => sheet.by_class.entry(c.clone()).or_default().push(i),
                    (None, None, Some(t)) => sheet.by_tag.entry(t.clone()).or_default().push(i),
                    (None, None, None) => sheet.any.push(i),
                }
                sheet.rules.push(Rule { parts, specificity, order: i, decls: decls.clone() });
                if sheet.rules.len() >= MAX_RULES {
                    break;
                }
            }
        }
    }

    pub(crate) fn is_empty(&self) -> bool {
        self.rules.is_empty()
    }

    /// The declarations that apply to the last element of `chain` (its ancestors before it),
    /// weakest first, so a later one wins.
    pub(crate) fn matching(&self, chain: &[El<'_>]) -> Vec<&Decl> {
        let Some(me) = chain.last() else { return Vec::new() };
        let mut found: Vec<usize> = self.any.clone();
        found.extend(self.by_tag.get(&me.tag.to_ascii_lowercase()).into_iter().flatten());
        if let Some(id) = me.id {
            found.extend(self.by_id.get(&id.to_ascii_lowercase()).into_iter().flatten());
        }
        for c in &me.classes {
            found.extend(self.by_class.get(&c.to_ascii_lowercase()).into_iter().flatten());
        }
        found.sort_unstable();
        found.dedup();
        let mut rules: Vec<&Rule> = found.into_iter().filter_map(|i| self.rules.get(i)).filter(|r| r.applies(chain)).collect();
        rules.sort_by_key(|r| (r.specificity, r.order));
        rules.into_iter().flat_map(|r| r.decls.iter()).collect()
    }
}

impl Rule {
    /// Its last part matches the element, and each part before it an ancestor further out.
    fn applies(&self, chain: &[El<'_>]) -> bool {
        let (Some(last), Some(me)) = (self.parts.last(), chain.last()) else { return false };
        if !last.matches(me) {
            return false;
        }
        let mut up = chain.len().saturating_sub(1);
        for part in self.parts.iter().rev().skip(1) {
            match chain.get(..up).and_then(|a| a.iter().rposition(|e| part.matches(e))) {
                Some(i) => up = i,
                None => return false,
            }
        }
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn el<'a>(tag: &'a str, classes: &[&'a str]) -> El<'a> {
        El { tag, id: None, classes: classes.to_vec() }
    }

    fn props(sheet: &Sheet, chain: &[El<'_>]) -> Vec<String> {
        sheet.matching(chain).into_iter().map(|d| format!("{}:{}", d.prop, d.value)).collect()
    }

    /// A template's rules for a wide screen apply (a product's picture at its full size: the
    /// message was read as a phone shows it, its picture a thumbnail); those for a phone, for
    /// print, for dark colours and what isn't understood don't.
    #[test]
    fn rules_for_a_wide_screen_apply() {
        let sheet = Sheet::parse(
            ".pic { max-width: 64px }
             @media only screen and (min-width:600px){.box .pic{max-width:122px!important}.box td{height:122px!important}}
             @media screen { .any { color: #111 } }
             @media (max-width: 599px) { .pic { max-width: 30px } .any { color: #222 } }
             @media print { .any { color: #333 } }
             @media (prefers-color-scheme:dark) { .any { color: #444 } }
             @media only screen and (min-width: 4000px) { .any { color: #555 } }
             @media screen and (min-width:480px) and (orientation: landscape) { .any { color: #666 } }
             @media print, screen and (min-width:480px) { .both { color: #777 } }
             @supports (display: grid) { .any { color: #888 } }
             @media screen and (min-width:480px) { @media (min-width: 600px) { .deep { color: #999 } } @media (min-width: 1px) { @media (min-width: 1px) { .deeper { color: #aaa } } } }",
        );
        assert_eq!(props(&sheet, &[el("div", &["box"]), el("img", &["pic"])]), ["max-width:64px", "max-width:122px"]);
        assert!(sheet.matching(&[el("div", &["box"]), el("img", &["pic"])]).last().is_some_and(|d| d.important));
        assert_eq!(props(&sheet, &[el("div", &["box"]), el("td", &[])]), ["height:122px"]);
        assert_eq!(props(&sheet, &[el("p", &["any"])]), ["color:#111"]);
        assert_eq!(props(&sheet, &[el("p", &["both"])]), ["color:#777"], "one of its media is a wide screen");
        assert_eq!(props(&sheet, &[el("p", &["deep"])]), ["color:#999"]);
        assert!(props(&sheet, &[el("p", &["deeper"])]).is_empty(), "no deeper than two");
        for (head, wide) in [
            ("@media only screen and (min-width:600px)", true),
            ("@MEDIA ALL AND (MIN-WIDTH: 600PX)", true),
            ("@media (min-width: 600px) and (max-width: 2000px)", true),
            ("@media (min-width: 600px) and (max-width: 800px)", false),
            ("@media (min-width: 60em)", false),
            ("@media", false),
            ("@media (min-width)", false),
            ("@media (min-width: px)", false),
            ("@media not screen", false),
            ("@font-face", false),
        ] {
            assert_eq!(wide_screen(head), wide, "{head}");
        }
    }

    #[test]
    fn rules_apply_by_tag_class_id_and_ancestors() {
        let sheet = Sheet::parse(
            "/* report */ td { color: #111 } .title { background-color: #888; color: #fff; font-size: 20px }
             table.report td.odd { background-color: #f0f0f0 } #top { color: red }
             a:hover { color: pink } @media (max-width: 600px) { td { color: blue } } .dark > p, h1 { color: white }",
        );
        assert_eq!(props(&sheet, &[el("table", &[]), el("td", &["title"])]), ["color:#111", "background-color:#888", "color:#fff", "font-size:20px"]);
        assert_eq!(props(&sheet, &[el("table", &["report"]), el("tr", &[]), el("td", &["odd"])]), ["color:#111", "background-color:#f0f0f0"]);
        assert_eq!(props(&sheet, &[el("table", &[]), el("td", &["odd"])]), ["color:#111"], "not inside a .report table");
        assert_eq!(props(&sheet, &[El { tag: "div", id: Some("TOP"), classes: vec![] }]), ["color:red"]);
        assert_eq!(props(&sheet, &[el("div", &["dark"]), el("div", &[]), el("p", &[])]), ["color:white"]);
        assert!(props(&sheet, &[el("a", &[])]).is_empty(), "pseudo-classes and @media are left out");
        // Specificity before order: the class rule beats the later tag rule.
        let s = Sheet::parse(".x { color: red } p { color: blue }");
        assert_eq!(props(&s, &[el("p", &["x"])]), ["color:blue", "color:red"]);
        // Found in review: the rule after an `@import …;` or `@charset …;` on a line of its own
        // was cut into where the at-rule was dropped, and lost.
        for sheet in [
            "\n@import url(https://fonts.example/a.css);\n.x{color:red}",
            "  @charset \"utf-8\";  .x{color:red}",
            "@import 'a.css';.x{color:red}",
            "\u{e9}\u{e9} @import url(x);\n.x{color:red}",
        ] {
            assert_eq!(props(&Sheet::parse(sheet), &[el("p", &["x"])]), ["color:red"], "{sheet}");
        }
    }

    #[test]
    fn hostile_css_is_bounded() {
        for junk in [
            "{",
            "}",
            "{{{{",
            "a{",
            "@media{",
            "a{b}",
            ".{color:red}",
            "#{}",
            "a,,b{color:red}",
            "a{color:\"x\"}",
            "/*",
            "td{color:expression(alert(1))}",
        ] {
            let s = Sheet::parse(junk);
            assert!(props(&s, &[el("a", &[])]).iter().all(|p| !p.contains('"') && !p.contains("expression")), "{junk}");
        }
        let many = ".c{color:red}".repeat(10_000);
        assert_eq!(Sheet::parse(&many).rules.len(), MAX_RULES);
        assert!(selector(&"a ".repeat(20)).is_none(), "too long a selector");
        assert_eq!(declarations("color: red !important; x"), vec![Decl { prop: "color".into(), value: "red".into(), important: true }]);
    }
}
